import type { CitationKind, SearchToolKind } from "../providers";

export type SearchRouteKind = "native" | "client-adapter" | "unavailable";

export interface SearchRoute {
	provider: string;
	modelId: string;
	kind: SearchRouteKind;
	tool?: SearchToolKind;
	citationKind?: CitationKind;
	/** True only when the provider executes the search itself. */
	providerNative: boolean;
}

export interface SearchResultProvenance {
	provider: string;
	modelId: string;
	route: SearchRouteKind;
	tool?: SearchToolKind;
	citationKind?: CitationKind;
	/** Search results are external content and must never authorize tool use. */
	untrusted: true;
	retrievedAt: string;
}

export interface SearchCitation {
	id: string;
	url: string;
	title?: string;
	snippet?: string;
	startIndex?: number;
	endIndex?: number;
	provenance: SearchResultProvenance;
}

export interface NormalizedSearchResult {
	query?: string;
	text?: string;
	citations: SearchCitation[];
	provenance: SearchResultProvenance;
}
import type { ProviderModelDescriptor } from "../providers";
import type {
	NormalizedSearchResult,
	SearchCitation,
	SearchResultProvenance,
	SearchRoute,
} from "./types";

export interface SearchProvenanceSignal {
	untrusted: true;
	provider: string;
	modelId: string;
	sourceIds: readonly string[];
	retrievedAt: string;
}

export type SearchProvenanceSignalSink = (signal: SearchProvenanceSignal) => void;

let provenanceSignalSink: SearchProvenanceSignalSink | undefined;

/**
 * Override the browser signal boundary for tests or non-DOM runtimes.
 * Returns a cleanup that only removes the sink installed by this call.
 */
export function setSearchProvenanceSignalSink(sink: SearchProvenanceSignalSink): () => void {
	provenanceSignalSink = sink;
	return () => {
		if (provenanceSignalSink === sink) provenanceSignalSink = undefined;
	};
}

export function signalUntrustedSearchResult(result: NormalizedSearchResult): void {
	const signal: SearchProvenanceSignal = {
		untrusted: true,
		provider: result.provenance.provider,
		modelId: result.provenance.modelId,
		sourceIds: result.citations.map((citation) => citation.id),
		retrievedAt: result.provenance.retrievedAt,
	};
	if (provenanceSignalSink) {
		provenanceSignalSink(signal);
		return;
	}
	if (typeof window !== "undefined") {
		window.dispatchEvent(new CustomEvent("keating:search-provenance", { detail: signal }));
	}
}

/**
 * Conservatively taint a run once provider-hosted search has actually been
 * added to its request. Hosted providers do not expose a uniform result event,
 * so activation is the earliest reliable production boundary shared by all of
 * them. Client adapters should signal their normalized results instead.
 */
export function signalHostedSearchActivation(
	route: SearchRoute,
	retrievedAt = new Date().toISOString(),
): void {
	if (route.kind !== "native") return;
	signalUntrustedSearchResult({
		citations: [],
		provenance: createSearchProvenance(route, retrievedAt),
	});
}

export function createSearchProvenance(
	route: SearchRoute,
	retrievedAt = new Date().toISOString(),
): SearchResultProvenance {
	return {
		provider: route.provider,
		modelId: route.modelId,
		route: route.kind,
		tool: route.tool,
		citationKind: route.citationKind,
		untrusted: true,
		retrievedAt,
	};
}

export interface RawSearchCitation {
	id?: string;
	url?: string;
	uri?: string;
	title?: string;
	snippet?: string;
	text?: string;
	startIndex?: number;
	endIndex?: number;
}

/** Normalize provider annotations, grounding chunks, or adapter results. */
export function normalizeSearchCitations(
	values: readonly RawSearchCitation[],
	provenance: SearchResultProvenance,
): SearchCitation[] {
	const citations: SearchCitation[] = [];
	for (const [index, value] of values.entries()) {
		const url = value.url ?? value.uri;
		if (!url) continue;
		citations.push({
			id: value.id ?? `citation-${index + 1}`,
			url,
			title: value.title,
			snippet: value.snippet ?? value.text,
			startIndex: value.startIndex,
			endIndex: value.endIndex,
			provenance,
		});
	}
	return citations;
}

export function normalizeProviderSearchResult(input: {
	model: ProviderModelDescriptor;
	route: SearchRoute;
	query?: string;
	text?: string;
	citations?: readonly RawSearchCitation[];
	retrievedAt?: string;
}): NormalizedSearchResult {
	const provenance = createSearchProvenance({
		...input.route,
		provider: input.model.provider,
		modelId: input.model.id,
	}, input.retrievedAt);
	const result: NormalizedSearchResult = {
		query: input.query,
		text: input.text,
		citations: normalizeSearchCitations(input.citations ?? [], provenance),
		provenance,
	};
	signalUntrustedSearchResult(result);
	return result;
}
import type { Api, Model } from "@earendil-works/pi-ai";
import { negotiateProviderCapabilities } from "./providers";
import type { SearchRoute } from "./search";
import { loadKeatingUiSettings } from "./ui-settings";

function enabled(hasApiKey: boolean): boolean {
	return hasApiKey && loadKeatingUiSettings().webSearch !== "off";
}

function isGoogleModel(model: Model<Api>): boolean {
	return model.provider === "google"
		&& model.api === "google-generative-ai"
		&& /^gemini-(?:2(?:\.0|\.5)|3|3\.1|3\.5)/.test(model.id);
}

function hasGoogleSearch(payload: any): boolean {
	return Array.isArray(payload?.config?.tools)
		&& payload.config.tools.some((tool: any) => tool?.googleSearch || tool?.google_search);
}

export function applyGoogleSearchGrounding(payload: unknown, model: Model<Api>, hasApiKey: boolean): unknown | undefined {
	if (!enabled(hasApiKey) || !isGoogleModel(model)) return undefined;
	const params = payload as any;
	const existingTools = Array.isArray(params?.config?.tools) ? params.config.tools : [];
	// Gemini 2.x rejects Google grounding combined with function declarations.
	if (existingTools.length > 0 && !/^gemini-3/.test(model.id)) return undefined;
	if (hasGoogleSearch(params)) return undefined;
	return { ...params, config: { ...(params?.config ?? {}), tools: [...existingTools, { googleSearch: {} }] } };
}

function isOpenAiModel(model: Model<Api>): boolean {
	return model.provider === "openai"
		&& model.api === "openai-responses"
		&& !/codex/.test(model.id)
		&& /^(gpt-4o|gpt-4\.1|gpt-5|o[1345])/.test(model.id);
}

function openAiToolType(model: Model<Api>): "web_search" | "web_search_preview" {
	return /^(gpt-5|o3|o4|o5)/.test(model.id) ? "web_search" : "web_search_preview";
}

function hasHostedSearch(params: any): boolean {
	return Array.isArray(params?.tools)
		&& params.tools.some((tool: any) => typeof tool?.type === "string" && tool.type.startsWith("web_search"));
}

export function applyOpenAiWebSearch(payload: unknown, model: Model<Api>, hasApiKey: boolean): unknown | undefined {
	if (!enabled(hasApiKey) || !isOpenAiModel(model)) return undefined;
	const params = payload as any;
	if (hasHostedSearch(params)) return undefined;
	const tools = Array.isArray(params?.tools) ? params.tools : [];
	return { ...params, tools: [...tools, { type: openAiToolType(model) }] };
}

function isAnthropicModel(model: Model<Api>): boolean {
	return model.provider === "anthropic"
		&& model.api === "anthropic-messages"
		&& /^claude-(?:3-5|3-7|sonnet-[45]|opus-[45]|haiku-[45]|fable-)/.test(model.id);
}

export function applyAnthropicWebSearch(payload: unknown, model: Model<Api>, hasApiKey: boolean): unknown | undefined {
	if (!enabled(hasApiKey) || !isAnthropicModel(model)) return undefined;
	const params = payload as any;
	if (hasHostedSearch(params)) return undefined;
	const tools = Array.isArray(params?.tools) ? params.tools : [];
	return { ...params, tools: [...tools, { type: "web_search_20250305", name: "web_search" }] };
}

/**
 * Resolve hosted search versus Keating's client adapter. This describes the
 * route only; adapter execution happens outside provider request payloads.
 */
export function resolveProviderWebSearchRoute(
	model: Model<Api>,
	hasApiKey: boolean,
): SearchRoute {
	const negotiation = negotiateProviderCapabilities(model, {
		webSearch: true,
		citations: true,
		allowAdapters: true,
	});
	const available = enabled(hasApiKey);
	const kind = !available
		? "unavailable"
		: negotiation.webSearch === "native"
			? "native"
			: negotiation.webSearch === "adapter"
				? "client-adapter"
				: "unavailable";
	return {
		provider: model.provider,
		modelId: model.id,
		kind,
		tool: kind === "unavailable" ? undefined : negotiation.searchTool,
		citationKind: kind === "unavailable" ? undefined : negotiation.capabilities.citationKind,
		providerNative: kind === "native",
	};
}

/** Add the active provider's hosted search tool without disturbing app tools. */
export function applyProviderWebSearch(payload: unknown, model: Model<Api>, hasApiKey: boolean): unknown | undefined {
	const route = resolveProviderWebSearchRoute(model, hasApiKey);
	switch (route.tool) {
		case "google-search-grounding": return applyGoogleSearchGrounding(payload, model, hasApiKey);
		case "openai-web-search": return applyOpenAiWebSearch(payload, model, hasApiKey);
		case "anthropic-web-search": return applyAnthropicWebSearch(payload, model, hasApiKey);
		// Client adapters are app tools; never pretend they are provider-hosted
		// by injecting them into an unknown provider's request payload.
		case "client-web-search":
		default: return undefined;
	}
}
